// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract LogFileHelper {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        // Keep amount in a wide but safe domain: at least MinSum and not absurdly large.
        amount = bound(amount, 1 ether, 100 ether);
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);

        // Setup required to reach Collect's happy path: give c a live LogFile.
        LogFileHelper logFile = new LogFileHelper();
        c.SetLogFile(address(logFile));

        // Fund the actor so Deposit can be made and Collect's ether transfer succeeds.
        vm.deal(actor, amount);

        // Actor deposits exactly `amount`, so balances[actor] == amount >= MinSum and >= amount.
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 balBefore = c.balances(actor);
        if (balBefore < c.MinSum() || balBefore < amount) {
            return;
        }

        // Call Collect and record whether it succeeded. On the reference it should succeed
        // (Log is live, actor can receive ether) and reduce actor's balance by amount.
        vm.prank(actor);
        bool ok;
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = c.balances(actor);

        // General rule: a successful Collect must decrease the caller's recorded balance
        // by exactly the amount collected. The mutant deletes the subtraction, so on a
        // successful Collect the balance does NOT decrease.
        assertTrue(!ok || balAfter == balBefore - amount);
    }
}
